def emit(x, y, s, size, color, bold=False, raw=None):
    if raw is None:
        raw = any(c in "<>&" for c in s)
    st = f' fontSize="{size}" color="{color}" fontFamily="{FAM}"'
    if bold: st += ' fontWeight="BOLD"'
    if raw:
        s2 = s.replace("&amp;", "&")   # CDATA 原样：& 不转义、实体不解码
        return f'<Positioned left="{x}" top="{y}"><T airst="{st}" ext>{s2}</T></Positioned>'  # 占位，下方修正
    return f'<Positioned left="{x}" top="{y}"><Text{st}>{s}</Text></Positioned>' if False else \
           f'<Positioned left="{x}" top="{y}"><Text{st} maxLines="1" overflow="CLIP">{s}</Text></Positioned>'

