# -*- coding: utf-8 -*-
"""A20: 24点无重叠标注地图 (1600×1100)。
映射: 像素锚点 = (280+10.4x, 920-7.6y), 逻辑原点左下(y向上)。
布局: 程序求解 — 紧贴候选(8向, 锚距<=24) 优先, 失败则右侧外栏槽位(折线引导)。
审计: 盒距>=4、盒-盘不相交、线不入盒、交叉<=3、边界, 全部精确计算(1e-6)。
"""
import io, sys, json, math, os
sys.stdout = io.TextIOWrapper(sys.stdout.buffer, encoding="utf-8")

RUN = "20261016T164020-m1"
D = f"outputs/{RUN}/A20"; TD = f"tmp/{RUN}/A20"
os.makedirs(D, exist_ok=True); os.makedirs(TD, exist_ok=True)

EPS = 1e-6
MAP = dict(l=280.0, t=160.0, r=1320.0, b=920.0)
CANVAS = (1600.0, 1100.0)
DOT_D = 12.0
FS = 20.0

def anchor(x, y):
    return (280.0 + 10.4 * x, 920.0 - 7.6 * y)

_markers = json.load(open("tasks/A20-dense-annotation/inputs/markers.json", encoding="utf-8"))
PT = {m["id"]: dict(id=m["id"], name=m["name"], value=m["value"], x=m["x"], y=m["y"],
                    ax=anchor(m["x"], m["y"])[0], ay=anchor(m["x"], m["y"])[1],
                    d=DOT_D) for m in _markers}
ORDER = [f"M{i:02d}" for i in range(1, 25)]
TOP3 = sorted(ORDER, key=lambda k: (-PT[k]["value"], k))[:3]
TOPRANK = {pid: i + 1 for i, pid in enumerate(TOP3)}
print("TOP3:", TOPRANK)

def est(s):                      # 20px 文本宽估计(CJK 20 / latin-digit 11.4 / · 11 / space 5.6)
    w = 0.0
    for ch in s:
        w += 11.4 if ord(ch) < 0x2E80 else 20.0
    return w

def ltext(p, top3=False):
    v = f"{p['value']}"
    if top3:
        v += f" · TOP{TOPRANK[p['id']]}"
    return f"{p['id']} · {p['name']}", v

def box_dims(p, lines=1):
    l1, l2 = ltext(p, p["id"] in TOP3)
    if lines == 1:
        t = f"{p['id']} · {p['name']} · {p['value']}" + (f" · TOP{TOPRANK[p['id']]}" if p["id"] in TOP3 else "")
        return est(t) + 24.0, 36.0, [t]
    return max(est(l1), est(l2)) + 24.0, 60.0, [l1, l2]

# ── 灯具(轴/刻度/说明)作为占位对象参与排布检查 ──
AXIS_NUM_X = [(280 + 10.4 * v, v) for v in (0, 25, 50, 75, 100)]
AXIS_NUM_Y = [(920 - 7.6 * v, v) for v in (0, 25, 50, 75, 100)]
FURN = []
for x, v in AXIS_NUM_X:
    FURN.append(["axis-x", [x - 20, 926, x + 20, 952]])
for y, v in AXIS_NUM_Y:
    FURN.append(["axis-y", [230, y - 13, 272, y + 13]])
FURN.append(["axis-cap-x", [620, 956, 980, 984]])
FURN.append(["axis-cap-y", [168, 112, 372, 140]])

def disk(k):                     # (cx, cy, r)
    p = PT[k]; return (p["ax"], p["ay"], p["d"] / 2)

def box_disk(b, c):
    cx, cy, r = c
    dx = max(b[0] - cx, 0, cx - b[2]); dy = max(b[1] - cy, 0, cy - b[3])
    return (dx * dx + dy * dy) ** 0.5            # 0=相交/接触

def box_gap(a, b):
    dx = max(a[0] - b[2], b[0] - a[2], 0); dy = max(a[1] - b[3], b[1] - a[3], 0)
    if dx == 0 and dy == 0: return 0.0
    return (dx * dx + dy * dy) ** 0.5 if (dx and dy) else (dx or dy)

def box_anchor_dist(b, k):
    cx, cy, _ = disk(k)
    dx = max(b[0] - cx, 0, cx - b[2]); dy = max(b[1] - cy, 0, cy - b[3])
    return (dx * dx + dy * dy) ** 0.5

def candidates(p, lines, gap8=6.0):
    """8向紧贴候选: 盒边距锚盘 gap8, 锚点到盒 <=4+gap8+?? 由几何决定(<=24)"""
    w, h, _ = box_dims(p, lines)
    cx, cy = p["ax"], p["ay"]; edge = p["d"] / 2 + gap8
    out = []
    out.append((cx - w / 2, cy - edge - h, cx + w / 2, cy - edge))            # N
    out.append((cx - w / 2, cy + edge, cx + w / 2, cy + edge + h))            # S
    out.append((cx + edge, cy - h / 2, cx + edge + w, cy + h / 2))            # E
    out.append((cx - edge - w, cy - h / 2, cx - edge, cy + h / 2))            # W
    out.append((cx + 4, cy - edge - h, cx + 4 + w, cy - edge))                # NE
    out.append((cx - 4 - w, cy - edge - h, cx - 4, cy - edge))                # NW
    out.append((cx + 4, cy + edge, cx + 4 + w, cy + edge + h))                # SE
    out.append((cx - 4 - w, cy + edge, cx - 4, cy + edge + h))                # SW
    return out

def inside_bounds(b):
    return b[0] >= 0 and b[1] >= 0 and b[2] <= CANVAS[0] and b[3] <= CANVAS[1]

def frame_clean(b):
    """盒不得骑/穿主图框线(允许全内或全外)"""
    mx = not (b[2] < MAP["l"] and False)
    inx = b[0] > MAP["l"] and b[2] < MAP["r"]
    outx = b[2] <= MAP["l"] or b[0] >= MAP["r"]
    iny = b[1] > MAP["t"] and b[3] < MAP["b"]
    outy = b[3] <= MAP["t"] or b[1] >= MAP["b"]
    return (inx or outx) and (iny or outy)

placed = {}   # id -> dict(box, lines, dims)

def feasible(b, k, min_gap=6.0):
    if not inside_bounds(b) or not frame_clean(b):
        return False
    c = disk(k)
    for pid, g in placed.items():
        if box_gap(b, g["box"]) < 4.0 + EPS:
            return False
    for f in FURN:
        if box_gap(b, f[1]) < 4.0 + EPS:
            return False
    for pid in PT:
        if pid == k: continue
        if box_disk(b, disk(pid)) <= 1.5:      # 非本点盘: 不得相交或接触(留1.5px)
            return False
    if box_disk(b, c) <= 0.1:                  # 自有盘不遮
        return False
    return True

def anchor_dist_of(b, k):
    d = box_anchor_dist(b, k)
    return d

PLACE_ORDER = ["M21", "M11", "M12", "M06", "M07", "M08", "M09", "M10", "M13", "M04", "M05",
