# ── 几何审计 ──
def seg_cross(a, b, c, d):
    """返回交点列表(可能0/1/2?此处只处理1) + 共线重合标志"""
    (x1, y1), (x2, y2), (x3, y3), (x4, y4) = a, b, c, d
    r = (x2 - x1, y2 - y1); s = (x4 - x3, y4 - y3)
    denom = r[0] * s[1] - r[1] * s[0]
    if abs(denom) <= EPS:
        # 共线判定
        cross = (x3 - x1) * r[1] - (y3 - y1) * r[0]
        if abs(cross) <= EPS:
            # 判正长度重合
            t0 = ((x3 - x1) * r[0] + (y3 - y1) * r[1]) / (r[0] * r[0] + r[1] * r[1])
            t1 = t0 + (s[0] * r[0] + s[1] * r[1]) / (r[0] * r[0] + r[1] * r[1])
            lo, hi = min(t0, t1), max(t0, t1)
            if hi > EPS and lo < 1 - EPS and hi - lo > EPS:
                return [], True        # 正长度共线重合 → 违规
            # 端点接触也算交叉(仅当接触)
            if min(t0, t1) <= 1 + EPS and max(t0, t1) >= -EPS:
                pass
        return [], False
    t = ((x3 - x1) * s[1] - (y3 - y1) * s[0]) / denom
    u = ((x3 - x1) * r[1] - (y3 - y1) * r[0]) / denom
    if -EPS <= t <= 1 + EPS and -EPS <= u <= 1 + EPS:
        return [(x1 + t * r[0], y1 + t * r[1])], False
    return [], False

def seg_in_box(a, b, box, allow_touch_edge=True):
    """线段是否进入盒内部(端点接触自身盒边允许, 其他盒不得进入)"""
    # 用采样+解析: 分段入盒测试(线段潜在与盒相交)
    x1, y1 = a; x2, y2 = b
    l, t, r, bo = box
    # 粗裁剪
    if max(x1, x2) < l or min(x1, x2) > r or max(y1, y2) < t or min(y1, y2) > bo:
        return False
    # 采样
    n = max(2, int(max(abs(x2 - x1), abs(y2 - y1)) / 2) + 2)
    for i in range(n + 1):
        tt = i / n
        x = x1 + (x2 - x1) * tt; y = y1 + (y2 - y1) * tt
        if l + 0.05 < x < r - 0.05 and t + 0.05 < y < bo - 0.05:
            return True
    return False

viol = []
# 盒盒 / 盒盘 / 锚距
for i, ki in enumerate(ORDER):
    for kj in ORDER[i + 1:]:
        g = box_gap(placed[ki]["box"], placed[kj]["box"])
