    if box_disk(placed[k]["box"], c) <= 0:
        viol.append(("self_cover", k, None, 0))
# 检查轴件不与其他冲突(由 feasible 保证, 记录值)
for k in ORDER:
    b = placed[k]["box"]
    for f in FURN:
        g = box_gap(b, f[1])
        if g < 4.0 - EPS:
            viol.append(("furn", k, f[0], g))
# 线: 不入他盒 / 自盒终点可触边 / 盘不挡他线(附加严格) / 交叉计数
cross_pairs = []
for ka in LINES:
    for kb in LINES:
        if ka >= kb: continue
        count = 0; pts = []
        coll = False
        for sa in LINES[ka]:
            for sb in LINES[kb]:
                pts2, cl = seg_cross(sa[:2], sa[2:], sb[:2], sb[2:])
                coll = coll or cl
                for pt in pts2:
                    if all((pt[0] - q[0]) ** 2 + (pt[1] - q[1]) ** 2 > 1e-9 for q in pts):
                        pts.append(pt); count += 1
        if coll:
            viol.append(("collinear_overlap", ka, kb, 0))
        if count:
            cross_pairs.append((ka, kb, pts, count))
total_cross = sum(c for _, _, _, c in cross_pairs)
for k, segs in LINES.items():
    for s in segs:
        for kb in placed:
            b = placed[kb]["box"]
            own = (kb == k)
