                    viol.append(("line_in_own_box_deep", k, kb, 0))
        for pid in PT:
            if pid == k: continue
            c = disk(pid)
            # 线段到圆盘最短距
            x1, y1, x2, y2 = *s[:2], *s[2:]
            dx, dy = x2 - x1, y2 - y1
            L2 = dx * dx + dy * dy
            if L2 > 0:
                t = max(0, min(1, ((c[0] - x1) * dx + (c[1] - y1) * dy) / L2))
                px_, py_ = x1 + t * dx, y1 + t * dy
                d = math.hypot(px_ - c[0], py_ - c[1])
                if d < c[2] + 1.0:
                    viol.append(("line_graze_dot", k, pid, d))
print("cross pairs:", [(a, b, [[round(x, 2), round(y, 2)] for x, y in p], c) for a, b, p, c in cross_pairs], "total:", total_cross)
print("violations:", len(viol))
for v in viol[:12]:
    print("  ", v)

