    for f in FURN:
        if box_gap(b, f[1]) < 4.0: return False
    for pid in PT:
        if pid != k and box_disk(b, disk(pid)) < 1.5: return False
    if box_disk(b, disk(k)) <= 0.1: return False
    return True

