    """识别最差像素所属背景成分，记录证据说明。"""
    r, g, b = rgb
    if canvas == "portrait":
        anchors = [("ghost-ring", (540, 380), (240, 180)),
                   ("ghost-ring", (540, 380), (180, 180))]
    else:
        anchors = [("ghost-ring", (322, 344), (212, 158)),
                   ("ghost-ring", (322, 344), (158, 158))]
    for kind, c, radii in anchors:
        d = math.hypot(x - c[0], y - c[1])
        for rr in radii:
            if abs(d - rr) <= 4:
                return kind
    if r > 240 and g > 248 and b > 248:
        return "free-pill-white"
    if r < 40 and g < 60 and b < 80:
        return "url-chip-dark"
    if abs(d := math.hypot(x - c[0], y - c[1])) > 4 and r < 235 and g < 245:
        pass
    if (r, g, b) <= (11, 34, 55) or (r < 20 and g < 40 and b < 60):
        return "url-chip-dark"
    if r > 240 and g > 246:
        return "near-white"
    if abs(r - 19) < 40 and abs(g - 156) < 40 and abs(b - 217) < 40:
