# -*- coding: utf-8 -*-
"""B06 共享组件：通用绘制原语 + case 注册。视觉系统逐件自定，不共用版式。
字体纪律：CJK 字符串走 txt（Noto Sans CJK SC）；纯 ASCII 数字走 num（Inter）。
禁裸 '<'：用量词或全角符号。颜色均带 #。"""
import math

CJK = "Noto Sans CJK SC"
INTER = "Inter"


def wrap_dsl(w, h, body, bg):
    return ('<Snapshot background="%s" type="png">\n<Stack>\n'
            '<SizedBox width="%s" height="%s" />\n' % (bg, w, h)
            + "\n".join(body) + "\n</Stack>\n</Snapshot>\n")


def rect(s, x, y, w, h, color, radius=0, border=None):
    a = ('<Container left="%s" top="%s" width="%s" height="%s" backgroundColor="%s"'
         % (g(x), g(y), g(w), g(h), color))
    if radius:
        a += ' borderRadius="%s"' % g(radius)
    if border:
        a += ' border="%s"' % border
    a += " />"
    s.append(a)


def txt(s, x, y, content, size, color, bold=False, family=CJK, align=None, box_w=None):
    a = '<Text x="%s" y="%s" fontSize="%s" color="%s" fontFamily="%s"' % (
        g(x), g(y), g(size), color, family)
    if bold:
        a += ' fontWeight="bold"'
    if align:
        a += ' textAlign="%s"' % align
    if box_w:
        a += ' boxWidth="%s"' % g(box_w)
    a += ">%s</Text>" % esc(content)
    s.append(a)


def num(s, x, y, content, size, color, bold=False, align=None, box_w=None):
    txt(s, x, y, content, size, color, bold=bold, family=INTER, align=align, box_w=box_w)


def pill(s, x, y, label, accent, dark=False, size=18):
    glyph_w = len(label) * size * 1.06 + size
    rect(s, x, y - size - 2, glyph_w, size + 14, accent, (size + 14) / 2)
    is_cjk = any(ord(c) > 0x2E00 for c in label)
    fn = CJK if is_cjk else INTER
    txt(s, x, y - 2, label, size, "#FFFFFF" if not dark else "#1B2733",
        bold=True, family=fn, align="CENTER", box_w=glyph_w)
    return glyph_w


def lamp(s, x, y, color, r=7):
    rect(s, x, y, 2 * r, 2 * r, color, r)


def card(s, x, y, w, h, color="#FFFFFF", accent=None, r=14, border=None):
    if border is None and accent:
        border = '2 SOLID %s' % accent
    rect(s, x, y, w, h, color, r, border=border)


def line_thick(s, x0, y0, x1, y1, w, color, step=1):
    pts = []
    if abs(x1 - x0) >= abs(y1 - y0):
        n = max(int(abs(x1 - x0) / step), 1)
        for i in range(n + 1):
            t = i / n
            pts.append((x0 + t * (x1 - x0), y0 + t * (y1 - y0)))
    else:
        n = max(int(abs(y1 - y0) / step), 1)
        for i in range(n + 1):
            t = i / n
            pts.append((x0 + t * (x1 - x0), y0 + t * (y1 - y0)))
    for (px, py) in pts:
        rect(s, px - w / 2, py - w / 2, w, w, color, w / 2)


def dash_line(s, x0, y0, x1, y1, w, color, dash=8, gap=6):
    dx, dy = x1 - x0, y1 - y0
    L = math.hypot(dx, dy)
    if L <= 0:
        return
    ux, uy = dx / L, dy / L
    t = 0.0
    while t < L:
        t2 = min(t + dash, L)
        line_thick(s, x0 + ux * t, y0 + uy * t, x0 + ux * t2, y0 + uy * t2, w, color)
        t = t2 + gap


def arrow(s, x0, y0, x1, y1, w, color, head=12):
    ang = math.atan2(y1 - y0, x1 - x0)
    bx = x1 - head * math.cos(ang)
    by = y1 - head * math.sin(ang)
    line_thick(s, x0, y0, bx, by, w, color)
    left = (bx + (head * 0.7) * math.cos(ang + math.radians(140)),
            by + (head * 0.7) * math.sin(ang + math.radians(140)))
    right = (bx + (head * 0.7) * math.cos(ang - math.radians(140)),
             by + (head * 0.7) * math.sin(ang - math.radians(140)))
    poly_rows(s, [(x1, y1), left, right], color)


def poly_rows(s, pts, color, step=1):
    ysmin = min(p[1] for p in pts)
    ysmax = max(p[1] for p in pts)
    edges = [(pts[i], pts[(i + 1) % len(pts)]) for i in range(len(pts))]
    y = ysmin
    while y < ysmax:
        yc = y + 0.5
        xs = []
        for (x1, y1), (x2, y2) in edges:
            if (y1 <= yc) != (y2 <= yc):
                t = (yc - y1) / (y2 - y1)
                xs.append(x1 + t * (x2 - x1))
        if len(xs) >= 2:
            xs.sort()
            for k in range(0, len(xs) - 1, 2):
                w_seg = xs[k + 1] - xs[k]
                if w_seg > 0.35:
                    rect(s, xs[k], y, w_seg, 1, color)
        y += step


def hill_rows(s, cx, cy, rx, ry, color, step=1):
    rows = int(2 * ry / step)
    for i in range(rows):
        yc = -ry + (i + 0.5) * step
        t = yc / ry
        hw = rx * math.sqrt(max(0.0, 1.0 - t * t))
        if hw > 0.4:
            rect(s, cx - hw, cy + yc, 2 * hw, step, color)


def stadium(s, cx, cy, length, thick, deg, color):
    pts = []
    n = 26
    for i in range(n):
        t = i / (n - 1)
        pts.append((-length / 2 + t * length, -thick / 2 - thick * 0.07))
    for i in range(n):
        t = i / (n - 1)
        pts.append((-length / 2 + t * length, thick / 2 + thick * 0.07))
    m = transform_str(deg)
    pts = [(m[0] * x + m[1] * y, m[2] * x + m[3] * y) for x, y in pts]
    pts = [(cx + x, cy + y) for x, y in pts]
    rect_rows_for_poly(s, pts, color)


def rect_rows_for_poly(s, pts, color, step=1):
    ysmin = min(p[1] for p in pts)
    ysmax = max(p[1] for p in pts)
    edges = [(pts[i], pts[(i + 1) % len(pts)]) for i in range(len(pts))]
    y = ysmin
    while y < ysmax:
        yc = y + 0.5
        xs = []
        for (x1, y1), (x2, y2) in edges:
            if (y1 <= yc) != (y2 <= yc):
                t = (yc - y1) / (y2 - y1)
                xs.append(x1 + t * (x2 - x1))
        if len(xs) >= 2:
            xs.sort()
            for k in range(0, len(xs) - 1, 2):
                if xs[k + 1] - xs[k] > 0.35:
                    rect(s, xs[k], y, xs[k + 1] - xs[k], 1, color)
        y += step


def transform_str(deg):
    t = math.radians(deg)
    return [math.cos(t), math.sin(t), -math.sin(t), math.cos(t)]


def rot_text(s, cx, cy, content, size, color, deg, bold=False, family=CJK):
    t = transform_str(deg)
    a = ('<Text x="%s" y="%s" fontSize="%s" color="%s" fontFamily="%s" fontWeight="%s"'
         ' transform="matrix(%s,%s,%s,%s,0,0)">%s</Text>') % (
        g(cx), g(cy), g(size), color, family,
        "bold" if bold else "normal",
        fnum(t[0]), fnum(t[1]), fnum(t[2]), fnum(t[3]), esc(content))
    s.append(a)


def dot_text(s, x, y, dot_color, text, size, color, bold=False, dot_r=6):
    lamp(s, x, y + size * 0.32, dot_color, dot_r)
    txt(s, x + 2 * dot_r + 10, y, text, size, color, bold=bold)


CASES = []


def case(mark, w, h):
    def deco(fn):
        CASES.append((mark, w, h, fn))
        return fn
    return deco


def fnum(v):
    return ("%.4f" % v).rstrip("0").rstrip(".")


def g(v):
    n = ("%.2f" % float(v)).rstrip("0").rstrip(".")
    return n if n else "0"


def esc(t):
    return (t.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;"))

